  (68, 'Work From Home - Bereavement Allowance', 10, 'Up to 7 days of paid leave for immediate family bereavement, with option for additional unpaid leave upon manager approval.', 0.0, 'none', 5.0, 0.0, NULL, True, '2025-05-06T02:04:58.085683', '2025-10-28T04:03:00.950547'),
  (69, 'Work From Home - Professional Study Enhancement', 10, 'Provision of up to 15 days per year for continued professional education aligned with organizational needs.', 0.0, 'none', 30.0, 0.0, NULL, False, '2025-12-20T13:23:51.192107', '2025-12-23T02:07:42.431947'),
  (70, 'Work From Home - Extended Sabbatical Opportunity', 10, '6 months unpaid leave for employees with 15+ years of service, enabling personal growth or voluntary pursuits.', 0.0, 'none', 30.0, 0.0, NULL, True, '2025-12-15T13:23:51.192107', '2025-12-22T02:44:36.980521'),
  (71, 'Volunteer Leave - New Hire Community Service', 11, 'Offers new employees up to 16 hours for volunteer activities to encourage early community engagement.', 3.0, 'yearly', 6.0, 0.0, NULL, True, '2025-11-15T11:49:33.410517', '2025-12-08T12:08:52.824792'),
  (72, 'Volunteer Leave - Senior Executive Outreach', 11, 'Provides senior executives 5 days annually to lead and participate in strategic community outreach programs.', 3.0, 'yearly', 6.0, 0.0, '[{"yearsOfService": 5, "extraDays": 1}]', True, '2025-12-17T13:23:56.461169', '2025-12-18T09:02:42.549366'),
  (73, 'Volunteer Leave - Part-Time Worker Engagement', 11, 'Allows part-time employees 3 days per year to engage in volunteer work, promoting work-life balance and community involvement.', 0.0, 'none', 30.0, 0.0, NULL, True, '2025-09-22T23:07:56.486246', '2025-12-01T00:39:14.785684'),
  (74, 'Volunteer Leave - Long-Service Employee Contribution', 11, 'Grants employees with over 15 years of service up to 10 paid days a year for extensive volunteer commitments.', 0.0, 'none', 10.0, 0.0, '[{"yearsOfService": 5, "extraDays": 1}]', True, '2025-12-01T13:23:56.461169', '2025-12-17T15:22:29.801958'),
  (75, 'Extended Sabbatical for Senior Executives', 12, 'Eligibility for senior executives to take a 6-month sabbatical for personal growth after 15 years of corporate service.', 0.0, 'none', 10.0, 0.0, NULL, True, '2025-08-17T06:04:15.610938', '2025-09-24T12:22:56.327697');
