INSERT INTO "job_family_groups" ("id", "name", "description", "created_at", "updated_at") VALUES
  (1, 'Enterprise Operations Support', 'Focuses on administrative support, facilities management, office services, and operational efficiency in corporate environments.', '2025-03-26T21:58:27.796068', '2025-03-30T01:55:22.172958'),
  (2, 'Strategic Communications and Public Relations', 'Oversees brand messaging, media relations, corporate storytelling, stakeholder engagement, and crisis communication strategies.', '2025-05-30T09:33:45.357293', '2025-05-31T16:50:53.571454'),
  (3, 'Innovative Visual Solutions', 'Includes graphic designers, creative directors, multimedia artists, brand strategists, and visual content developers.', '2025-06-13T10:33:23.691676', '2025-06-17T02:39:24.380949'),
  (4, 'Client Relations and Assistance', 'Roles focused on managing client interactions, ensuring satisfaction, resolving inquiries, and maintaining service excellence.', '2025-05-31T15:12:24.157839', '2025-05-31T23:21:24.304876'),
  (5, 'Occupational Safety and Environmental Stewardship', 'Roles focusing on workplace safety, compliance management, hazard prevention, and sustainable environmental practices', '2025-01-21T11:43:38.995978', '2025-01-23T06:37:02.418833'),
  (6, 'Fiscal Operations and Management', 'Budget analysts, treasury coordinators, compliance officers, financial controllers, and audit management specialists in corporate settings.', '2025-08-07T12:26:25.840029', '2025-08-08T15:58:52.564961'),
  (7, 'Talent Management and Development', 'Focus on recruiting, employee retention, leadership training, performance management, and career progression programs.', '2025-05-15T07:26:01.192706', '2025-05-18T05:49:36.625293'),
  (8, 'Digital Systems Innovation', 'Focuses on developing adaptive IT solutions, enhancing cybersecurity measures, and driving digital transformation initiatives.', '2025-05-12T20:19:40.340743', '2025-05-16T23:36:35.740968'),
  (9, 'Regulatory Affairs and Governance', 'Roles include corporate compliance officers, regulatory analysts, legal advisors, and governance specialists ensuring adherence to laws and regulations.', '2025-06-05T19:27:39.552332', '2025-06-08T14:59:40.908401'),
  (10, 'Brand Engagement Strategy', 'Creative strategists, digital content creators, customer engagement specialists, market analysts, and brand optimization experts', '2025-07-28T05:19:23.406928', '2025-07-28T23:45:47.735792'),
  (11, 'Advisory and Strategic Consultancy', 'Expert advisors, strategic planners, project consultants, management analysts, and operational optimization specialists', '2025-05-18T14:09:48.470431', '2025-05-23T01:53:27.047153'),
  (12, 'Innovation and Product Advancement', 'Professionals leading prototype design, feasibility studies, and creating future-forward product innovations.', '2025-09-25T08:07:24.706791', '2025-09-29T02:09:26.057883'),
  (13, 'Strategic Vision and Execution', 'Focuses on long-term goal setting, resource alignment, competitive analysis, and strategic decision implementation.', '2025-05-09T08:26:16.806535', '2025-05-13T01:12:49.866282'),
  (14, 'Distribution Management and Fulfillment', 'Roles focused on inventory management, order processing, logistics coordination, and delivery optimization professionals', '2025-07-25T05:37:17.219669', '2025-07-29T14:42:31.511941'),
  (15, 'Revenue Growth Strategies', 'Roles focused on expanding market presence, forging strategic partnerships, enhancing client relationships, and driving sales performance initiatives.', '2025-03-09T01:18:28.211640', '2025-03-13T22:55:32.212688');
INSERT INTO "job_families" ("id", "name", "description", "created_at", "updated_at", "group_id") VALUES
  (1, 'Administrative Coordination', 'Manages office tasks, schedules, correspondence, and resource allocation to maintain organizational efficiency.', '2025-03-27T21:58:27.796068', '2025-03-28T09:57:13.362543', 1),
  (2, 'Facilities Management', 'Oversees the maintenance, safety, and functionality of physical corporate environments.', '2025-03-30T21:58:27.796068', '2025-03-31T14:09:46.442309', 1),
  (3, 'Operational Planning', 'Develops strategies for improving workflow and resource utilization in business processes.', '2025-03-27T21:58:27.796068', '2025-03-28T06:49:46.920450', 1),
  (4, 'Office Services Management', 'Coordinates office services, including mail, reception, and supply procurement to support business operations.', '2025-03-30T21:58:27.796068', '2025-03-31T10:16:29.545987', 1),
  (5, 'Logistics and Asset Management', 'Handles inventory control, asset tracking, and distribution of resources across the enterprise.', '2025-03-28T21:58:27.796068', '2025-03-29T09:08:44.333645', 1),
  (6, 'Media Relations', 'Manages relationships with media outlets to promote positive company coverage and manage communications.', '2025-06-03T09:33:45.357293', '2025-06-03T22:22:11.425688', 2),
  (7, 'Crisis Communication', 'Develops strategies to manage and communicate during corporate crises effectively.', '2025-06-01T09:33:45.357293', '2025-06-02T01:06:53.637165', 2),
  (8, 'Brand Messaging', 'Crafts and oversees communication strategies that promote brand values and identity.', '2025-06-02T09:33:45.357293', '2025-06-03T06:09:37.262792', 2),
  (9, 'Stakeholder Engagement', 'Builds and maintains relationships with internal and external stakeholders for mutual benefit.', '2025-06-02T09:33:45.357293', '2025-06-03T00:53:41.499488', 2),
  (10, 'Corporate Storytelling', 'Creates compelling narratives to communicate company vision, values, and achievements through various media.', '2025-05-31T09:33:45.357293', '2025-05-31T20:24:39.298223', 2),
  (11, 'Graphic Design', 'Develops visual concepts and designs for branding, advertising, and corporate identity.', '2025-06-15T10:33:23.691676', '2025-06-16T05:31:59.988828', 3),
  (12, 'Creative Direction', 'Leads creative projects and teams in developing innovative visual content strategies.', '2025-06-15T10:33:23.691676', '2025-06-15T19:37:15.327860', 3),
  (13, 'Brand Strategy', 'Defines visual identity and brand positioning through strategic design and marketing efforts.', '2025-06-17T10:33:23.691676', '2025-06-17T12:29:14.345285', 3),
  (14, 'Visual Content Development', 'Produces multimedia content, including videos, animations, and digital graphics for communication.', '2025-06-15T10:33:23.691676', '2025-06-16T08:05:11.420255', 3),
  (15, 'Multimedia Artistry', 'Creates integrated visual experiences using a variety of artistic mediums and digital tools.', '2025-06-16T10:33:23.691676', '2025-06-16T13:44:03.535606', 3),
  (16, 'Client Support Services', 'Provides frontline assistance to clients to address inquiries and resolve issues promptly.', '2025-06-03T15:12:24.157839', '2025-06-04T04:21:48.273320', 4),
  (17, 'Customer Relationship Management', 'Manages client interactions to foster long-term relationships and drive satisfaction.', '2025-06-03T15:12:24.157839', '2025-06-03T22:50:10.146741', 4),
  (18, 'Service Excellence Management', 'Focuses on delivering high-quality service standards to ensure client satisfaction.', '2025-06-04T15:12:24.157839', '2025-06-05T08:18:53.314011', 4),
  (19, 'Inquiry Resolution', 'Handles and resolves customer queries and complaints through effective communication.', '2025-06-04T15:12:24.157839', '2025-06-05T11:01:05.213206', 4),
  (20, 'Account Management', 'Oversees client accounts to ensure services align with business needs and expectations.', '2025-06-04T15:12:24.157839', '2025-06-04T23:19:03.697531', 4),
  (21, 'Workplace Safety Management', 'Develops safety policies and procedures to ensure compliance and prevent workplace incidents.', '2025-01-22T11:43:38.995978', '2025-01-22T19:30:12.582387', 5),
  (22, 'Environmental Compliance', 'Ensures adherence to environmental laws and regulations to promote sustainability.', '2025-01-22T11:43:38.995978', '2025-01-23T06:19:38.830536', 5),
