  (52, 'Management Analysis', 'Analyzes organizational processes to identify areas of improvement and optimize performance and efficiency.', '2025-05-20T14:09:48.470431', '2025-05-21T11:35:52.903605', 11),
  (53, 'Operational Optimization', 'Focuses on streamlining operations to enhance productivity and reduce costs across the business.', '2025-05-20T14:09:48.470431', '2025-05-21T10:56:38.781161', 11),
