  (1542, 'Lead Sales Operations Specialist - Real Estate', 'Oversees real estate sales operations, ensuring smooth process alignment with performance goals and operational excellence.', 'LS-1542', 8, 'ACTIVE', '2025-03-19T01:18:28.211640', '2025-03-19T04:06:27.288929', 369, 74, 15),
  (1543, 'Lead Sales Operations Specialist - Media Advertising', 'Guides media advertising sales operations, focusing on efficiencies that align with strategic sales performance targets.', 'LS-1543', 8, 'INACTIVE', '2025-03-18T01:18:28.211640', '2025-03-20T06:15:54.682371', 369, 74, 15),
  (1544, 'Lead Sales Operations Specialist - Cloud Computing', 'Manages cloud computing sales operations, streamlining procedures to enhance efficiency and ensure alignment with sales goals.', 'LS-1544', 7, 'ACTIVE', '2025-03-16T01:18:28.211640', '2025-03-18T16:10:49.099097', 369, 74, 15),
  (1545, 'Lead Sales Operations Specialist - Pharmaceutical', 'Directs sales operations in pharmaceuticals, enhancing processes for efficiency and strategic alignment with performance objectives.', 'LS-1545', 8, 'ACTIVE', '2025-03-17T01:18:28.211640', '2025-03-18T01:00:35.507052', 369, 74, 15),
  (1546, 'Director of Sales Performance - Digital Media', 'Leads digital media sales strategies, aligning training and operational processes with business objectives to enhance results.', 'DX-1546', 10, 'ACTIVE', '2025-03-15T01:18:28.211640', '2025-03-16T16:12:46.570687', 370, 74, 15),
  (1547, 'Director of Sales Performance - Subscription Models', 'Directs subscription sales strategies, focusing on improved results through targeted training and process enhancements.', 'DX-1547', 9, 'ACTIVE', '2025-03-20T01:18:28.211640', '2025-03-21T02:43:29.031530', 370, 74, 15),
  (1548, 'Director of Sales Performance - Consulting Services', 'Guides sales strategies in consulting, aligning incentives and training to amplify business objectives and sales outcomes.', 'DX-1548', 10, 'ACTIVE', '2025-03-16T01:18:28.211640', '2025-03-17T19:33:49.595519', 370, 74, 15),
  (1549, 'Director of Sales Performance - Hospitality Sector', 'Oversees sales strategies in hospitality, directing efforts to boost performance through aligned process and training initiatives.', 'DX-1549', 10, 'ACTIVE', '2025-03-16T01:18:28.211640', '2025-03-17T22:22:48.369299', 370, 74, 15),
  (1550, 'Director of Sales Performance - Consumer Technologies', 'Heads consumer tech sales performance, directing strategies to integrate training and processes for maximized business results.', 'DX-1550', 10, 'ACTIVE', '2025-03-18T01:18:28.211640', '2025-03-20T10:59:38.049437', 370, 74, 15),
  (1551, 'Revenue Analyst - SaaS Platform', 'Analyze the financial data of our SaaS platform to identify revenue optimization opportunities, focusing on customer lifetime value and churn reduction.', 'RO-1551', 5, 'ACTIVE', '2025-03-20T01:18:28.211640', '2025-03-22T04:19:39.962392', 371, 75, 15),
  (1552, 'Revenue Analyst - E-commerce Data', 'Examine transactional data in the e-commerce space, pinpointing trends and strategies to boost sales performance and profit margins.', 'RO-1552', 5, 'ACTIVE', '2025-03-19T01:18:28.211640', '2025-03-22T06:15:17.389129', 371, 75, 15),
  (1553, 'Financial Analyst - Mobile Solutions', 'Evaluate the financial performance of our mobile solutions division, uncovering insights that drive revenue growth and improve fiscal health.', 'RO-1553', 5, 'ACTIVE', '2025-03-17T01:18:28.211640', '2025-03-19T10:03:33.472509', 371, 75, 15),
  (1554, 'Revenue Analyst - Digital Security', 'Assess digital security service offerings to uncover revenue opportunities, enhancing profitability through refined pricing strategies.', 'RO-1554', 4, 'ACTIVE', '2025-03-16T01:18:28.211640', '2025-03-18T16:39:54.979331', 371, 75, 15),
  (1555, 'Data-Driven Revenue Analyst - Growth Team', 'Collaborate with growth teams to leverage financial analytics, identifying new revenue streams and optimizing existing operations.', 'RO-1555', 4, 'ACTIVE', '2025-03-14T01:18:28.211640', '2025-03-16T17:11:54.137281', 371, 75, 15),
  (1556, 'Growth Specialist - Cloud Services', 'Develop and execute strategic plans to optimize pricing and increase market share for our suite of cloud service offerings.', 'RG-1556', 4, 'ACTIVE', '2025-03-19T01:18:28.211640', '2025-03-20T16:44:43.145189', 372, 75, 15),
  (1557, 'Sales Strategy Specialist - AI Products', 'Focus on boosting revenue through tailored sales strategies for our artificial intelligence product lines, enhancing market penetration.', 'RG-1557', 5, 'DRAFT', '2025-03-20T01:18:28.211640', '2025-03-22T02:17:36.332667', 372, 75, 15),
  (1558, 'Revenue Booster - Subscription Models', 'Craft strategies to grow revenue within our subscription-based services, focusing on customer retention and upsell opportunities.', 'RG-1558', 4, 'ACTIVE', '2025-03-19T01:18:28.211640', '2025-03-21T16:42:31.556721', 372, 75, 15),
  (1559, 'Revenue Growth Specialist - B2B Solutions', 'Design and implement initiatives to accelerate revenue growth in our B2B solutions segment, targeting enterprise client acquisitions.', 'RG-1559', 6, 'ACTIVE', '2025-03-21T01:18:28.211640', '2025-03-24T04:42:50.995126', 372, 75, 15),
  (1560, 'Pricing Strategy Specialist - Consumer Goods', 'Innovate pricing models for our consumer products, aiming to capture a larger market share while maximizing revenue potential.', 'RG-1560', 5, 'ACTIVE', '2025-03-17T01:18:28.211640', '2025-03-17T13:22:08.069514', 372, 75, 15),
  (1561, 'Profitability Strategist - Tech Innovations', 'Lead strategy design for optimizing profits in our tech innovations sector, balancing research investments with potential financial returns.', 'SP-1561', 7, 'ACTIVE', '2025-03-14T01:18:28.211640', '2025-03-14T20:43:08.252567', 373, 75, 15),
  (1562, 'Revenue Optimizer - Energy Solutions', 'Create comprehensive profitability strategies for our energy solutions, focusing on cost efficiency without sacrificing growth prospects.', 'SP-1562', 7, 'DRAFT', '2025-03-14T01:18:28.211640', '2025-03-14T20:36:07.675946', 373, 75, 15),
  (1563, 'Profitability Lead - Global Operations', 'Develop and deploy strategies to improve profitability across global operations, harmonizing regional diversity with unified goals.', 'SP-1563', 6, 'ACTIVE', '2025-03-20T01:18:28.211640', '2025-03-21T09:13:41.780765', 373, 75, 15),
