  (1, 'Improve overall customer satisfaction score by 15%', 'Enhance customer service processes and product quality to increase satisfaction from 70 to 85% by year-end.', 96, 16, 'completed', NULL, NULL, NULL, False, False, '2025-10-05T13:32:22.123555', '2025-11-29T13:32:22.123555', '2025-06-18T08:30:07.328910', '2025-11-29T13:32:22.123555'),
  (2, 'Reduce operational costs by 10% annually', 'Implement cost-saving measures across departments to decrease costs from $50M to $45M this fiscal year.', 16, 176, 'offTrack', NULL, NULL, 'Delayed due to resource constraints and competing priorities.', False, False, '2025-12-20T13:32:22.123555', '2025-12-21T13:32:22.123555', '2025-03-30T19:27:53.007265', '2025-05-05T11:31:48.314834'),
  (3, 'Expand into three international markets', 'Initiate operations in Europe, Asia, and South America, achieving a combined revenue of $5M by year-end.', 88, 98, 'completed', NULL, NULL, NULL, False, False, '2025-11-23T13:32:22.123555', '2025-11-23T13:32:22.123555', '2025-03-25T06:08:18.044870', '2025-11-23T13:32:22.123555'),
  (4, 'Launch a cybersecurity initiative company-wide', 'Develop and implement new security protocols to reduce data breaches by 75% in the next 12 months.', 88, 188, 'offTrack', NULL, NULL, 'Delayed due to resource constraints and competing priorities.', False, True, '2025-11-02T13:32:22.123555', '2025-12-01T13:32:22.123555', '2025-07-20T06:15:41.786695', '2025-09-27T05:09:58.833591'),
  (5, 'Increase employee engagement score by 20%', 'Boost engagement through training programs and incentives, aiming to raise the score from 60 to 80% within a year.', 86, 136, 'incomplete', NULL, NULL, 'Facing technical blockers that may impact delivery timeline.', False, True, '2025-10-27T13:32:22.123555', '2025-11-01T13:32:22.123555', '2025-06-04T21:38:26.541370', '2025-07-04T22:27:19.436773'),
  (6, 'Achieve a 20% reduction in product delivery time', 'Optimize supply chain processes to decrease average delivery from 5 days to 4 days by the end of Q3.', 100, 39, 'offTrack', NULL, NULL, 'Delayed due to resource constraints and competing priorities.', False, True, '2025-11-26T13:32:22.123555', '2025-12-12T13:32:22.123555', '2025-12-12T11:39:27.835393', '2025-12-22T00:13:47.779378'),
  (7, 'Develop and introduce a new mobile application', 'Launch a user-friendly app on both iOS and Android platforms with a target of 100,000 downloads within six months.', 26, 185, 'completed', NULL, NULL, NULL, False, False, '2025-12-01T13:32:22.123555', '2025-12-08T13:32:22.123555', '2025-03-12T10:24:41.869161', '2025-12-08T13:32:22.123555'),
  (8, 'Increase brand awareness by 30% in target demographics', 'Utilize social media and influencer marketing to raise brand visibility and engagement by Q2 end.', 50, 199, 'completed', NULL, NULL, NULL, False, False, '2025-11-20T13:32:22.123555', '2025-12-01T13:32:22.123555', '2025-05-16T20:20:37.947472', '2025-12-01T13:32:22.123555'),
  (9, 'Improve employee retention rate by 25%', 'Enhance company culture and benefits package to increase retention from 60% to 85% within the fiscal year.', 76, 194, 'completed', NULL, NULL, NULL, False, False, '2025-10-19T13:32:22.123555', '2025-10-30T13:32:22.123555', '2025-09-03T02:22:31.774669', '2025-10-30T13:32:22.123555'),
