  (80, 28, 'Increase User-Generated Content', 'Achieve a 30% growth in user-generated content submissions on social platforms', 'percentage', 30.0, 'percentage', 9.0, NULL, NULL, 'Achieved 30 percent progress by launching a new user engagement feature. Planning to conduct a user feedback survey next month.', '2025-05-17T12:02:23.029608', '2025-05-20T05:27:52.097122'),
  (81, 28, 'Engagement Through Interactive Polls', 'Implement weekly interactive polls with a 30% response rate increase', 'percentage', 30.0, 'percentage', 9.0, NULL, NULL, 'Launched two interactive polls this week with positive engagement. Currently analyzing feedback. Planning to introduce more such activities next month.', '2025-05-15T12:02:23.029608', '2025-05-28T20:46:07.075419'),
  (82, 29, 'Complete Skill Module Training', 'Ensure 80% of employees finish at least one new skill module', 'percentage', 80.0, 'percentage', 24.0, NULL, NULL, NULL, '2025-07-16T22:24:09.338571', '2025-08-14T18:12:28.648027'),
  (83, 29, 'Increase Training Participation', 'Achieve a 20% increase in training session attendance company-wide from previous year', 'percentage', 20.0, 'percentage', NULL, NULL, NULL, 'Despite the goal being marked complete, participation metrics show zero progress. Need to identify effective strategies to engage team members and increase involvement.', '2025-07-14T22:24:09.338571', '2025-07-27T03:55:27.435761'),
  (84, 29, 'Achieve Employee Certification', 'Certify 50% of employees in at least one new skill area by end of year', 'percentage', 50.0, 'percentage', 15.0, NULL, NULL, NULL, '2025-07-15T22:24:09.338571', '2025-07-29T19:40:19.867958'),
